from collections import deque
states = set(range(6))
alphabet = ['a','b','c']
eps = {1:{2,4}}
trans = {(0,'a'):{1}, (2,'b'):{3}, (4,'c'):{5}}
start = 0
accept = {3,5}

def closure(S):
    S = set(S)
    stack = list(S)
    while stack:
        q = stack.pop()
        for r in eps.get(q, set()):
            if r not in S:
                S.add(r)
                stack.append(r)
    return frozenset(S)

def move(S, a):
    T = set()
    for q in S:
        T |= trans.get((q, a), set())
    return T

start_set = closure({start})
dfa_states = []
seen = {start_set}
queue = deque([start_set])
while queue:
    S = queue.popleft()
    dfa_states.append(S)
    for a in alphabet:
        T = closure(move(S, a))
        if T and T not in seen:
            seen.add(T)
            queue.append(T)

names = {S: chr(65+i) for i, S in enumerate(dfa_states)}
dead = 'E'
full = {}
for S in dfa_states:
    name = names[S]
    for a in alphabet:
        T = closure(move(S, a))
        full[(name, a)] = names[T] if T else dead
for a in alphabet:
    full[(dead, a)] = dead

final = {names[S] for S in dfa_states if S & accept}
all_states = set(names.values()) | {dead}
groups = [final, all_states - final]
changed = True
while changed:
    changed = False
    new_groups = []
    for g in groups:
        g = set(g)
        if len(g) <= 1:
            new_groups.append(g)
            continue
        sigs = {}
        for s in g:
            sig = []
            for a in alphabet:
                t = full[(s, a)]
                for i, gg in enumerate(groups):
                    if t in gg:
                        sig.append(i)
                        break
            sigs.setdefault(tuple(sig), set()).add(s)
        if len(sigs) > 1:
            changed = True
            new_groups.extend(sigs.values())
        else:
            new_groups.append(g)
    groups = new_groups

print(len(dfa_states))
print(len(groups) - 1)
